# --- s012 Book I d.1 q.5 (= Ord. I d.1 p.3, nn. 159–?)
n("n271","s012-01","Quinta et vltima questio prime distinctionis","la","source","= *Ord.* I d. 1 p. 3 qq. 1–5 (n. 159 *utrum Deo conveniat frui*; n. 161 *utrum viator fruatur*; n. 163 *utrum peccator fruatur*…). Gorris compresses Scotus’s five questions on the subject of enjoyment into one.","verified")
n("n272","s012-02","Deus est spera intelligibilis cuius centrum est vbique: circumferentia nusquam.","la","source","*Liber XXIV philosophorum*, prop. 2. Scotus quotes it in *Ord.* I d. 1 n. 174 (*unde ait ille sapiens quod Deus est sphaera intellectualis, cuius centrum ubique et circumferentia nusquam*). Gorris’s gloss traces the ascription: to Hermes Trismegistus by Alexander of Hales (*Summa* I), and to *Secundus philosophus* by Bartholomaeus Anglicus, *De proprietatibus rerum*.","verified")
n("n273","s012-02","in propetario suo","la","textual","A *propetario* for *proprietario*, i.e. Bartholomaeus Anglicus, *De proprietatibus rerum* (I.16?). B not checked.","to-verify")
n("n274","s012-02","de vita philosophorum","la","source","The *Vita Secundi philosophi* circulated with Vincent of Beauvais and in the pseudo-Burley *De vita et moribus philosophorum*. A gnomic definition of God (*Quid est deus?*) appears in Secundus’s answers to Hadrian, but not in this form.","to-verify")
n("n275","s012-03","per actum amicicie vult deo in se bene esse","la","source","*Ord.* I d. 1 n. 161 ff. contrasts *actus concupiscentiae* (desire) with *actus amicitiae* (enjoyment). Willing well to the beloved for his own sake is Aristotle’s friendship formula (*Rhet.* II.4; *EN* VIII.2).","certain")
n("n276","s012-03","Et si Aug. videtur dicere contrarium","la","source","Augustine, *De div. qu. 83* q. 30 (*non absurde credantur etiam bestiae frui cibo*), cited by Scotus in this question.","to-verify")
n("n277","s012-02","Secundus the Philosopher","en","translation","*secundi philosophi*: not ‘the second philosopher’ but Secundus, the silent philosopher of Hadrian’s time.")
n("n278","s012-03","unrestrainable","en","translation","*irrefrenabili*: an act that nothing can check.")
# --- B collation (full): B23R–B24L
n("n1050","s012-02","Decidendo questionem in aliquibus libris","la","textual","B: *Dicendo ad questionem in aliquibus reperitur* (without *libris*).","certain")
n("n1051","s012-02","prima parte summe est Hermetis","la","textual","B: *prima parte summe et hermetis*. A's *est* is needed for the sense.","certain")
upd("n273",text="A and B both print *propetario* (B with the *pro* abbreviation), for *proprietario*. This refers to Bartholomaeus Anglicus, *De proprietatibus rerum* (I.16?); the book and chapter have not been verified.")
n("n1052","s012-03","quia esset finis sui ipsius","la","textual","B: *quia sic esset finis sui ipsius*.","certain")
n("n1053","s012-03","ideo fruitur illo","la","textual","B: *ergo illo fruitur*.","certain")
n("n1054","s012-03","actu irrefrenabili","la","textual","B: *actu irreferibili*, 'an act not referable [to anything further]'. This may well be the better reading for enjoyment as rest in the last end, but A is construable and the translation keeps *irrefrenabili* (note n278).","probable")
n("n1055","s012-03","obiectum quod sonat","la","textual","B: *obiectum quod satiat*. A's *sonat* ('sounds') gives no proper sense, so the translation follows B (note n1056).","certain")
n("n1056","s012-03","an object that satisfies [it]","en","translation","Follows B *satiat*; A prints *sonat* (see note n1055).","certain")
upd("n278",append="B reads *irreferibili*; see note n1054.")
